@MainActor final class AchievementReferenceTests:XCTestCase {
 func testActualSourceAndNativeTranscriptStates()async throws{
  let env=ProcessInfo.processInfo.environment;guard env["PIYALI_REFERENCE_PREVIEW_TESTS"] == "1",env["PIYALI_OFFLINE_TESTS"] == "1",UUID(uuidString:env["PIYALI_TEST_IDENTITY_SCOPE"] ?? "") != nil else{throw XCTSkip("Isolated source preview required")}
  let states=try ContentLibrary.decode(JSONValue.self,url:try XCTUnwrap(Bundle(for:Self.self).url(forResource:"achievement-panels",withExtension:"json"))),scene=try XCTUnwrap(UIApplication.shared.connectedScenes.compactMap{$0 as? UIWindowScene}.first),old=scene.windows.first{$0.isKeyWindow};defer{old?.makeKey()}
  for(language,theme)in[("en","light"),("ar","dark")]{for name in["empty","earned","robots","pending","storage"]{
   let state=states[name],window=UIWindow(windowScene:scene);window.frame=CGRect(x:0,y:0,width:402,height:874);let config=WKWebViewConfiguration();config.websiteDataStore = .nonPersistent();let web=WKWebView(frame:window.frame,configuration:config),vc=UIViewController();vc.view=web;window.rootViewController=vc;window.makeKeyAndVisible();web.scrollView.contentInsetAdjustmentBehavior = .never;defer{web.stopLoading();window.isHidden=true;window.rootViewController=nil}
   web.load(URLRequest(url:URL(string:"http://127.0.0.1:5181/__piyali-achievements?state=\(name)&language=\(language)&theme=\(theme)")!));var ready=false;for _ in 0..<600{ready=(try? await web.evaluateJavaScript("document.fonts.status==='loaded' && !!document.querySelector('.achievement-card canvas')"))as?Bool == true;if ready{break};try await Task.sleep(for:.milliseconds(50))};XCTAssertTrue(ready,"Source \(name) \(language)");guard ready else{let detail=(try? await web.evaluateJavaScript("JSON.stringify({url:location.href,body:document.body.innerText,errors:window.achievementErrors||[]})"))as?String ?? "No browser state";let a=XCTAttachment(string:detail);a.name="Achievement preview loading failure";a.lifetime = .keepAlways;add(a);return};_=try await web.evaluateJavaScript("document.querySelectorAll('canvas').forEach(e=>e.style.animationPlayState='paused')");try await Task.sleep(for:.milliseconds(300))
   let source=XCTAttachment(image:try await web.takeSnapshot(configuration:nil));source.name="Source Achievements \(name) \(language)";source.lifetime = .keepAlways;add(source)
   let geometry=(try? await web.evaluateJavaScript("JSON.stringify([...document.querySelectorAll('.achievement-collection,.achievement-collection header,h2,h3,p,button,.achievement-card,.chakra-modal__footer')].slice(0,35).map(e=>{let r=e.getBoundingClientRect(),s=getComputedStyle(e);return{text:e.textContent,x:r.x,y:r.y,w:r.width,h:r.height,font:s.font,lineHeight:s.lineHeight,padding:s.padding,bg:s.backgroundColor}}))"))as?String ?? "[]";let metrics=XCTAttachment(data:Data(geometry.utf8),uniformTypeIdentifier:"public.json");metrics.name="Source Achievements \(name) \(language) geometry";metrics.lifetime = .keepAlways;add(metrics);web.stopLoading();window.isHidden=true;window.rootViewController=nil
   window.rootViewController=UIHostingController(rootView:AchievementCollectionPanel(language:language,records:state["records"],syncPending:state["pending"].boolean,storageWarning:state["storageWarning"].boolean,initialTab:state["host"].string,animatedCharacters:false,onClose:{}).environment(\.dynamicTypeSize,.large).preferredColorScheme(theme == "dark" ? .dark:.light));window.makeKeyAndVisible();try await Task.sleep(for:.milliseconds(350));let shot=XCTAttachment(image:UIGraphicsImageRenderer(bounds:window.bounds).image{_ in window.drawHierarchy(in:window.bounds,afterScreenUpdates:true)});shot.name="Native Achievements \(name) \(language)";shot.lifetime = .keepAlways;add(shot);window.isHidden=true;window.rootViewController=nil
